ty'?1:0 }}"></td>@endforeach<td><button type="button" class="btn btn-danger remove-line">×</button></td></tr></tbody></table><button type="button" id="add-sale-line" class="btn btn-default">Add Item</button></div><div class="ran-card"><div class="row"><div class="col-md-2"><label>Invoice Discount</label><input type="number" step="any" name="discount_amount" value="0" class="form-control"></div><div class="col-md-2"><label>Invoice Tax</label><input type="number" step="any" name="tax_amount" value="0" class="form-control"></div><div class="col-md-2"><label>Rounding</label><input type="number" step="any" name="rounding_amount" value="0" class="form-control"></div><div class="col-md-6"><label>Notes</label><input name="notes" class="form-control"></div><div class="col-md-12"><label>Terms</label><textarea name="terms" class="form-control"></textarea></div></div><div class="text-right"><button class="btn btn-primary">Save Draft Sale</button></div></div></form>@push('ran-js')<script>$(function(){let i=1;$('#add-sale-line').click(function(){let r=$('#sale-lines tbody tr:first').clone();r.find('input,select').each(function(){this.name=this.name.replace(/lines\[\d+\]/,'lines['+i+']');$(this).val(this.tagName==='SELECT'?'':0);});$('#sale-lines tbody').append(r);i++;});$(document).on('click','.remove-line',function(){if($('#sale-lines tbody tr').length>1)$(this).closest('tr').remove();});$(document).on('change','.lot-select',function(){let o=$(this).find(':selected'),r=$(this).closest('tr');r.find('[name$="[unit_price]"]').val(o.data('price')||0);r.find('[name$="[gross_weight]"]').val(o.data('gross')||0);r.find('[name$="[net_weight]"]').val(o.data('net')||0);r.find('[name$="[stone_weight]"]').val(o.data('stone')||0);});});</script>@endpush@endsection
